-- calc_substrates_answer_key_fail_count
-- Field: Substrates.AnswerKeyFailCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_substrates_answer_key_fail_count(p_substrate_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM answer_key_results WHERE substrate = (SELECT NULLIF(substrate_id, '') FROM substrates WHERE substrate_id = p_substrate_id) AND outcome = 'fail'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_substrates_answer_key_ok
-- Field: Substrates.AnswerKeyOk
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_substrates_answer_key_ok(p_substrate_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_substrates_answer_key_result_count(p_substrate_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_substrates_answer_key_fail_count(p_substrate_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

