-- calc_substrates_conformant
-- Field: Substrates.Conformant
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_substrates_conformant(p_substrate_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_substrates_answer_key_ok(p_substrate_id), FALSE) AND COALESCE(calc_substrates_reflection_ok(p_substrate_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

